// =============================================================================
// Wings Travel Agency — SINGLE-FILE server (everything in one file on purpose)
// Zero external dependencies. Run with:  node server.js
// Then open: http://localhost:3000
//
// This is a deliberately single-file version of the project, built to avoid
// folder-upload issues when deploying via a web UI (GitHub upload, etc).
// It behaves identically to the multi-file version.
// =============================================================================

const fs = require('fs');
const path = require('path');
const http = require('http');
const crypto = require('crypto');
const { URL } = require('url');

// ---- .env loader (optional — only needed once you add RateHawk keys) ------
const ENV_PATH = path.join(__dirname, '.env');
if (fs.existsSync(ENV_PATH)) {
  const lines = fs.readFileSync(ENV_PATH, 'utf-8').split('\n');
  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;
    const eq = trimmed.indexOf('=');
    if (eq === -1) continue;
    const key = trimmed.slice(0, eq).trim();
    const val = trimmed.slice(eq + 1).trim();
    if (!(key in process.env)) process.env[key] = val;
  }
}

const PORT = process.env.PORT || 3000;

