// =============================================================================
// DATABASE — single file, db.json, sitting right next to server.js
// =============================================================================

const DB_PATH = path.join(__dirname, 'db.json');

function readDb() {
  if (!fs.existsSync(DB_PATH)) {
    const empty = { customers: [], bookings: [] };
    fs.writeFileSync(DB_PATH, JSON.stringify(empty, null, 2));
    return empty;
  }
  const raw = fs.readFileSync(DB_PATH, 'utf-8');
  try { return JSON.parse(raw); } catch (e) { return { customers: [], bookings: [] }; }
}
function writeDb(db) {
  fs.writeFileSync(DB_PATH, JSON.stringify(db, null, 2));
}
function findOrCreateCustomer({ firstName, lastName, email, phone, guestId }) {
  const db = readDb();
  let customer = db.customers.find(c => c.email === email);
  if (!customer) {
    customer = { id: 'cus_' + crypto.randomBytes(6).toString('hex'), firstName, lastName, email, phone, guestId, createdAt: new Date().toISOString() };
    db.customers.push(customer);
    writeDb(db);
  }
  return customer;
}
function generateConfirmationCode() {
  return 'WNG-' + Math.floor(100000 + Math.random() * 900000);
}
function createBooking(data) {
  const db = readDb();
  const booking = {
    id: 'bkg_' + crypto.randomBytes(6).toString('hex'),
    confirmationCode: generateConfirmationCode(),
    ...data,
    status: 'confirmed',
    paymentStatus: 'paid_demo',
    createdAt: new Date().toISOString()
  };
  db.bookings.push(booking);
  writeDb(db);
  return booking;
}
function getBooking(id) {
  const db = readDb();
  return db.bookings.find(b => b.id === id || b.confirmationCode === id) || null;
}
function listBookingsByGuestId(guestId) {
  const db = readDb();
  return db.bookings.filter(b => b.guestId === guestId).sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));
}
function cancelBooking(id) {
  const db = readDb();
  const booking = db.bookings.find(b => b.id === id);
  if (!booking) return null;
  booking.status = 'cancelled';
  writeDb(db);
  return booking;
}

// =============================================================================
// HTTP helpers
// =============================================================================

function sendJson(res, status, data) {
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(data));
}
function getCookie(req, name) {
  const header = req.headers.cookie;
  if (!header) return null;
  const match = header.split(';').map(c => c.trim()).find(c => c.startsWith(name + '='));
  return match ? decodeURIComponent(match.split('=')[1]) : null;
}
function ensureGuestId(req, res) {
  let guestId = getCookie(req, 'wings_guest');
  if (!guestId) {
    guestId = 'guest_' + crypto.randomBytes(8).toString('hex');
    res.setHeader('Set-Cookie', `wings_guest=${guestId}; Path=/; Max-Age=${60 * 60 * 24 * 365}`);
  }
  return guestId;
}
function readBody(req) {
  return new Promise((resolve, reject) => {
    let data = '';
    req.on('data', chunk => (data += chunk));
    req.on('end', () => {
      if (!data) return resolve({});
      try { resolve(JSON.parse(data)); } catch (e) { reject(e); }
    });
    req.on('error', reject);
  });
}

// =============================================================================
// API routes
// =============================================================================

async function handleApi(req, res, url) {
  const guestId = ensureGuestId(req, res);
  const parts = url.pathname.split('/').filter(Boolean);

  try {
    if (req.method === 'GET' && parts[1] === 'hotels' && !parts[2]) {
      const q = url.searchParams;
      const results = await provider.searchHotels({
        destination: q.get('destination') || '',
        checkin: q.get('checkin') || '',
        checkout: q.get('checkout') || '',
        guests: q.get('guests') || '2'
      });
      return sendJson(res, 200, { results, demoMode: isDemoMode });
    }

    if (req.method === 'GET' && parts[1] === 'hotels' && parts[2]) {
      const q = url.searchParams;
      const hotel = await provider.getHotelDetails({
        hotelId: parts[2],
        checkin: q.get('checkin') || '',
        checkout: q.get('checkout') || '',
        guests: q.get('guests') || '2'
      });
      if (!hotel) return sendJson(res, 404, { error: 'Hotel not found' });
      return sendJson(res, 200, { hotel, demoMode: isDemoMode });
    }

    if (req.method === 'GET' && parts[1] === 'quote') {
      const q = url.searchParams;
      const quote = await provider.getQuote({
        hotelId: q.get('hotelId'),
        roomId: q.get('roomId'),
        checkin: q.get('checkin'),
        checkout: q.get('checkout'),
        guests: q.get('guests') || '2'
      });
      return sendJson(res, 200, { quote });
    }

    if (req.method === 'POST' && parts[1] === 'bookings' && !parts[2]) {
      const body = await readBody(req);
      const { hotelId, roomId, checkin, checkout, guests, guestDetails, specialRequests, couponCode } = body;
      if (!hotelId || !roomId || !checkin || !checkout) {
        return sendJson(res, 400, { error: 'חסרים פרטי הזמנה (מלון/חדר/תאריכים)' });
      }
      if (!guestDetails || !guestDetails.firstName || !guestDetails.email) {
        return sendJson(res, 400, { error: 'חסרים פרטי אורח (שם/אימייל)' });
      }
      const quote = await provider.getQuote({ hotelId, roomId, checkin, checkout, guests });
      const customer = findOrCreateCustomer({
        firstName: guestDetails.firstName, lastName: guestDetails.lastName || '',
        email: guestDetails.email, phone: guestDetails.phone || '', guestId
      });
      const booking = createBooking({
        customerId: customer.id, guestId,
        hotelId: quote.hotelId, hotelName: quote.hotelName, hotelImage: quote.hotelImage, hotelLocation: quote.hotelLocation,
        roomId: quote.roomId, roomName: quote.roomName,
        checkin: quote.checkin, checkout: quote.checkout, guests: quote.guests, nights: quote.nights,
        pricePerNight: quote.pricePerNight, totalPrice: quote.totalPrice, currency: quote.currency,
        specialRequests, couponCode
      });
      return sendJson(res, 201, { booking });
    }

    if (req.method === 'GET' && parts[1] === 'bookings' && parts[2]) {
      const booking = getBooking(parts[2]);
      if (!booking) return sendJson(res, 404, { error: 'Booking not found' });
      return sendJson(res, 200, { booking });
    }

    if (req.method === 'POST' && parts[1] === 'bookings' && parts[2] && parts[3] === 'cancel') {
      const booking = cancelBooking(parts[2]);
      if (!booking) return sendJson(res, 404, { error: 'Booking not found' });
      return sendJson(res, 200, { booking });
    }

    if (req.method === 'GET' && parts[1] === 'my-bookings') {
      return sendJson(res, 200, { bookings: listBookingsByGuestId(guestId) });
    }

    return sendJson(res, 404, { error: 'Unknown API route' });
  } catch (err) {
    console.error(err);
    return sendJson(res, 500, { error: err.message || 'Server error' });
  }
}

// =============================================================================
// Server
// =============================================================================

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, `http://${req.headers.host}`);

  if (url.pathname.startsWith('/api/')) {
    return handleApi(req, res, url);
  }

  const page = PAGES[url.pathname];
  if (page) {
    res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
    return res.end(page);
  }

  res.writeHead(404, { 'Content-Type': 'text/html; charset=utf-8' });
  res.end('<h1>404 — הדף לא נמצא</h1>');
});

server.listen(PORT, () => {
  console.log(`Wings Travel Agency server running at http://localhost:${PORT}`);
});
